BEGIN
  IF SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA')<>'LIMS_RUNTIME_LOCAL' THEN
    RAISE_APPLICATION_ERROR(-20001, 'Only LIMS_RUNTIME_LOCAL is allowed'); END IF;
