    RAISE_APPLICATION_ERROR(-20001, 'Session must be SYS or LIMS_RUNTIME_LOCAL'); END IF;
  SELECT VALUE INTO v_semantics FROM NLS_SESSION_PARAMETERS WHERE PARAMETER='NLS_LENGTH_SEMANTICS';
  IF v_semantics<>'BYTE' THEN RAISE_APPLICATION_ERROR(-20001, 'NLS_LENGTH_SEMANTICS must be BYTE'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='T_CORE_LES_DS';
  missing('T_CORE_LES_DS'):=n=0;
  IF n<>0 THEN verify_table('T_CORE_LES_DS'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='T_CORE_LES_DS_FIELD';
  missing('T_CORE_LES_DS_FIELD'):=n=0;
  IF n<>0 THEN verify_table('T_CORE_LES_DS_FIELD'); END IF;
