    SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='IDX_CORE_LES_DS_FIELD_DSID';
    IF n<>0 THEN RAISE_APPLICATION_ERROR(-20004, 'Index name collision'); END IF;
    SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='PK_CORE_LES_DS_FIELD';
    IF n<>0 THEN RAISE_APPLICATION_ERROR(-20004, 'Index name collision'); END IF;
  END IF;
  -- Every target has passed preflight before any DDL is executed.
  IF missing('T_CORE_LES_DS') THEN
    SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='T_CORE_LES_DS';
