    EXECUTE IMMEDIATE 'CREATE TABLE "T_CORE_LES_DS" ( "ID" NUMBER(20) NOT NULL , "SCOPE" VARCHAR2(16) NULL , "LESDSNAME" VARCHAR2(128) NULL , "SQLCONTENT" CLOB NULL , "SQLCLAUSE" VARCHAR2(512) NULL , "DISPLAYCATEGORY" VARCHAR2(32) NULL , "CREATEDBYID" VARCHAR2(32) NULL , "CREATEDBYNAME" VARCHAR2(64) NULL , "CREATEDTIME" DATE NULL , "CREATEDBYORGID" VARCHAR2(32) NULL , "CREATEDBYORGNAME" VARCHAR2(256) NULL , "ACTIVATEDFLAG" VARCHAR2(1) NULL , "ACTIVATEDBYID" VARCHAR2(32) NULL , "ACTIVATEDBYNAME" VARCHAR2(36) NULL , "ACTIVATEDTIME" DATE NULL )';
