    EXECUTE IMMEDIATE 'COMMENT ON COLUMN "T_CORE_LES_DS"."ID" IS ''主键''';
    EXECUTE IMMEDIATE 'COMMENT ON COLUMN "T_CORE_LES_DS"."SCOPE" IS ''作用域''';
